"""Self-contained scientific report; only real computed data, escaped sources."""
from html import escape
import json,csv,io

def candidates_csv(ranked):
    s=io.StringIO();w=csv.writer(s);w.writerow(['tier','rank','jid','formula','bandgap_TBmBJ_eV','hull_OptB88vdW_eV_per_atom','formation_OptB88vdW_eV_per_atom','SLME_reported_percent','source_url'])
    for tier,rows in ranked.items():
        for rank,r in enumerate(rows,1):
            p=r['properties'];w.writerow([tier,rank,r['jid'],r['formula'],p['gap_mbj'],p['hull_ev_atom'],p['formation_ev_atom'],p['slme_percent'],r['url']])
    return s.getvalue()

def methodology(config):return '''# MDE-001 — reproducible photovoltaic screening\n\nOriginal software Apache-2.0; JARVIS data CC BY4.0, NIST JARVIS / Kamal Choudhary et al., DOI10.6084/m9.figshare.6815699.v11. Normalization and computed analysis are modifications.\n\nConfiguration: \n```json\n'''+json.dumps(config,indent=2)+'''\n```\n\nAll records of the fixed2025-09-24 official bulk snapshot, not an outcome-selected sample. Validated composition/crystal identity; missing and nonfinite values remain missing, not zero. Zero gap/hull/SLME values are retained. Polymorphs remain separate JIDs.\n\nPrimary bandgap is TB-mBJ. optB88vdW gaps are distributed separately, never pooled. Hull and formation energy are separate optB88vdW descriptors; hull threshold is exploratory. StageA: gap/composition/optional dielectric filters, order by distance to configured target1.5eV. The target is the midpoint of the initial interval, not an asserted optimum. StageB: known hull below threshold, order by hull then gap distance. StageC: additionally reported SLME above threshold, order by SLME descending, hull then gap distance. JID breaks ties. No composite probability score.\n\nSensitivity compares three windows0.8–2.2,1.0–2.0,1.2–1.8eV and four hull thresholds0,0.05,0.1,0.2eV/atom. Coverage and top-ten Jaccard use explicit denominators. Missingness and eligibility changes differ from ranking-order changes. Correlations use paired complete cases; no causal interpretation.\n\nReported SLME is theoretical, not experimental efficiency. Per-record thickness/temperature are absent; no uniform-condition or independent optical validation claim. The snapshot contains dielectric diagonals, not full absorption spectra. No DFT simulation, synthesis or device experiment was performed.\n\nReproduce: run `python -m materials.cli run --data .local/materials` with the pinned source. Keep full cached response for `verify`; public normalized replay separately checks the analysis without network. See REPRODUCIBILITY.md.\n'''

def html_report(r):
    e=lambda x:escape(str(x));m=r['metrics'];d=r['dataset'];table=lambda heads,rows:'<div class="table"><table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    def number(x):return 'missing' if x is None else e(x)
    sections=''
    for tier,rows in r['candidate_lists'].items():
        sections+='<h3>'+e(tier)+' — '+e(m['screen_counts'][tier]['numerator'])+' candidates</h3>'+table(['Rank','JARVIS / formula','TB-mBJ gap / eV','Hull / eV atom⁻¹','SLME / %'],[[e(x['rank']),'<a href="'+e(x['url'])+'">'+e(x['jid'])+'</a><br>'+e(x['formula']),number(x['properties']['gap_mbj']),number(x['properties']['hull_ev_atom']),number(x['properties']['slme_percent'])] for x in rows[:20]])
    charts=''
    for method,dist in r['bandgap_distributions'].items():
        maximum=max((b['count'] for b in dist['bins']),default=1) or 1
        charts+='<h3>'+e(method)+' — N='+e(dist['available'])+' available, '+e(dist['missing'])+' missing</h3>'
        for b in dist['bins']:charts+='<div class="bar"><span>'+e(b['lower'])+'–'+e(b['upper'] if b['upper'] is not None else '∞')+' eV</span><meter min="0" max="'+e(maximum)+'" value="'+e(b['count'])+'"></meter><b>'+e(b['count'])+'</b></div>'
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>MDE-001 · Materials Discovery Engine</title><style>
body{font:16px/1.8 system-ui,sans-serif;color:#172229;background:#f5f3ed;max-width:1180px;margin:auto;padding:48px 24px}h1{font-size:clamp(36px,6vw,72px);font-weight:500;letter-spacing:-.05em;line-height:1.1}h2{margin-top:54px;font-weight:500;font-size:32px;line-height:1.2}a{color:#2f5d70}code{overflow-wrap:anywhere}.eyebrow{font:11px monospace;letter-spacing:.13em}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #cbd0ce;border-radius:15px}.stats>div{padding:22px}.stats b{font-size:30px;display:block}.stats span{font-size:12px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:12px;border-bottom:1px solid #d2d6d3;text-align:left;vertical-align:top}.table{overflow-x:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:#fffdf8;border:1px solid #d1d7d4;border-radius:12px;padding:20px}.bar{display:grid;grid-template-columns:130px 1fr 70px;gap:15px;margin:8px 0;font-size:12px}.bar meter{width:100%;height:24px}footer{border-top:1px solid #ccd2d0;margin-top:50px;padding-top:25px;font-size:13px}.notice{border-left:3px solid #9d8059;padding-left:20px}@media(max-width:700px){body{padding:24px 18px}.stats{grid-template-columns:1fr 1fr}.bar{grid-template-columns:100px 1fr 45px;gap:8px}}
</style></head><body><p class="eyebrow">MATTOCCIA LABS / RESEARCH ENGINES / ENGINE03 — MATTER</p><h1>Computational Screening<br>of Photovoltaic Materials.</h1><p class="notice">Public-data research screening, not new-material discovery or experimental photovoltaic efficiency. No DFT simulation or physical experiment performed.</p>'''+ '<p>Experiment MDE-001 · '+e(r['completed_at'])+' · analysis <code>'+e(r['analysis_sha256'])+'</code></p><div class="stats">'+''.join('<div><b>'+e(value)+'</b><span>'+e(label)+'</span></div>' for label,value in [('Records acquired',m['records_acquired']),('Valid unique materials',m['valid_unique_materials']),('Gap candidates',m['screen_counts']['gap_only']['numerator']),('Gap + hull + SLME candidates',m['screen_counts']['optical']['numerator'])])+'</div><h2>Objective and dataset</h2><p>Explore a fixed public JARVIS bulk-material snapshot for candidates warranting further computational or experimental research.</p><pre>'+e(json.dumps(d,indent=2))+'</pre><h2>Method and parameters</h2><p>TB-mBJ band-gap window and optional composition filter; known energy above hull; reported theoretical SLME. Each stage has an explicit, lexicographic ordering and JID tie break. Target gap is an exploratory midpoint, not an efficiency optimum.</p><pre>'+e(json.dumps({'configuration':r['configuration'],'ranking':r['ranking_method']},indent=2))+'</pre><h2>1 / Property distributions and exclusions</h2>'+charts+'<pre>'+e(json.dumps(m,indent=2))+'</pre><h2>2 / Reproducible candidates</h2><p>First20 rows of each ranking below; all eligible ranks are in the accompanying CSV. Formation energy is not substituted for missing hull energy.</p>'+sections+'<h2>3 / Comparative analysis</h2>'+table(['Gap window / eV','Hull max / eV atom⁻¹','Gap','Stability','Optical','Top10 overlap numerator / union'],[[e(str(x['gap_min'])+'–'+str(x['gap_max'])),e(x['hull_max']),e(x['gap_count']),e(x['stability_count']),e(x['optical_count']),e(str(x['top10_overlap_with_configured_optical']['numerator'])+' / '+str(x['top10_overlap_with_configured_optical']['denominator']))] for x in r['sensitivity']])+'<pre>'+e(json.dumps({'robust_candidates':r['robust_across_all12_criteria'],'comparisons':r['ranking_comparisons'],'chemical_groups':r['chemical_groups'],'paired_correlations':r['correlations'],'outlier_flags':r['outliers']},indent=2))+'</pre><h2>Source-level validation</h2><pre>'+e(json.dumps({'archive_and_geometry_checks':r.get('detail_checks',[]),'same_provider_rendering_checks':r.get('external_detail_checks',[])},indent=2))+'</pre><h2>Scientific limits</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in r['limitations'])+'</ul><h2>Sources and reproduction</h2><p>NIST JARVIS-DFT / Kamal Choudhary et al., <a href="https://doi.org/'+e(d['doi'])+'">'+e(d['doi'])+'</a>, <a href="https://creativecommons.org/licenses/by/4.0/">CC BY4.0</a>. Normalization and screening are modifications. No endorsement implied. Original software Apache-2.0.</p><p>Full dataset SHA256: <code>'+e(d['source']['sha256'])+'</code>. See MDE-001_MANIFEST.json and MDE-001_METHODOLOGY.md for pinned URL, versions, software, hashes and parameters.</p><footer>Run the local source release with the pinned official snapshot, then verify cached raw data without network. A normalized public replay is a separate numeric reproducibility check. Neither route replaces independent scientific validation or establishes device suitability.</footer></body></html>'

    summary='<h2>Research findings</h2><ol><li><b>Coverage.</b> '+e(m['availability']['gap_mbj']['numerator'])+' of '+e(m['valid_unique_materials'])+' valid materials have a TB-mBJ gap; '+e(m['valid_unique_materials']-m['availability']['gap_mbj']['numerator'])+' do not. Source methods remain separate.</li><li><b>Candidates.</b> '+e(m['screen_counts']['gap_only']['numerator'])+' pass the gap criteria; '+e(m['screen_counts']['stability']['numerator'])+' also pass hull and '+e(m['screen_counts']['optical']['numerator'])+' also pass reported SLME. These are existing database crystals, not new discoveries.</li><li><b>Sensitivity.</b> '+e(r['robust_across_all12_criteria']['count'])+' materials remain eligible across all twelve gap/hull combinations. Threshold choices and missingness affect interpretation.</li></ol>'
    differences=[c for c in r.get('external_detail_checks',[]) if c.get('reported_slme_differs')]
    source_note='<p class="notice">'+e(len(differences))+' of '+e(len(r.get('external_detail_checks',[])))+' separately acquired NIST pages report SLME different from the pinned snapshot. '+e('; '.join(c['jid']+': snapshot '+str(c['snapshot_slme_percent'])+'% versus page '+str(c['page_fields']['slme_percent'])+'%' for c in differences))+'. The cause and optical-condition equivalence are not established; ranking remains tied to the pinned snapshot, not an independent optical validation.</p>'
    return html.replace('<h2>Objective and dataset</h2>',summary+'<h2>Objective and dataset</h2>').replace('<h2>Source-level validation</h2>','<h2>Source-level validation</h2>'+source_note)
